        this.username = username;
        this.teamName = teamName;
    }
}

@Test
void 같은_타입() {
    em.clear();
    NameDto d = queryFactory
            .select(new QNameDto(team.name, member.username))   // 뒤바꿈
            .from(member).join(member.team, team)
            .where(member.username.eq("m1"))
            .fetchOne();
    System.out.println(d.getUsername() + " / " + d.getTeamName());
}

