-- 나눠 쓰는 법

// 조회 전용 (Q 타입을 만든다)
public record MemberSearchResult(String username, int age, String teamName) {
    @QueryProjection
    public MemberSearchResult { }
}

// API 응답 (순수하다)
public record MemberResponse(String username, int age, String teamName) {
    public static MemberResponse from(MemberSearchResult r) {
        return new MemberResponse(r.username(), r.age(), r.teamName());
    }
}

@Test
void 나눠서() {
    em.clear();
    List<MemberResponse> r = queryFactory
            .select(new QMemberSearchResult(
                    member.username, member.age, team.name))
            .from(member)
            .leftJoin(member.team, team)
            .limit(2)
            .fetch()
            .stream()
            .map(MemberResponse::from)
            .toList();
    r.forEach(System.out::println);
}

